/* ---------- 소리: 파일 없이 합성. 첫 누름 뒤에 켜짐 ---------- */
let AC=null,OUT=null;const ac=()=>{try{if(!AC){AC=new (window.AudioContext||window.webkitAudioContext)();OUT=AC.createGain();OUT.gain.value=.55;OUT.connect(AC.destination)}if(AC.state==='suspended')AC.resume()}catch(e){}return AC};
const nz=(fq,q,dur,g,type='bandpass',dl=0)=>{const a=ac();if(!a)return;try{const n=Math.max(1,a.sampleRate*dur|0),bf=a.createBuffer(1,n,a.sampleRate),d=bf.getChannelData(0);for(let i=0;i<n;i++)d[i]=(Math.random()*2-1)*(1-i/n);const s=a.createBufferSource(),f=a.createBiquadFilter(),G=a.createGain(),t0=a.currentTime+dl;s.buffer=bf;f.type=type;f.frequency.value=fq;f.Q.value=q;G.gain.setValueAtTime(g,t0);G.gain.exponentialRampToValueAtTime(.0001,t0+dur);s.connect(f).connect(G).connect(OUT);s.start(t0)}catch(e){}};
const tone=(fq,dur,g,dl=0,type='sine')=>{const a=ac();if(!a)return;try{const o=a.createOscillator(),G=a.createGain(),t0=a.currentTime+dl;o.type=type;o.frequency.setValueAtTime(fq,t0);G.gain.setValueAtTime(.0001,t0);G.gain.exponentialRampToValueAtTime(g,t0+.01);G.gain.exponentialRampToValueAtTime(.0001,t0+dur);o.connect(G).connect(OUT);o.start(t0);o.stop(t0+dur+.05)}catch(e){}};
