/* ---------- 여는 글 ---------- */
function intro(){const u=ov();/* 11/17 P16: 첫 화면을 포스터처럼. 뒤는 어둡게 가리지 않고, 카메라가 경주 반가 마을 위를 천천히 돎. 창은 왼쪽, 단청 띠와 금빛 제목 */
 u.o.classList.add('jd-intro');const H3=window.__H3;let tour=null;try{const P=H3&&H3.P;const back=P?[P.x,P.z,P.y]:null;let yaw=-.85;const go=()=>{const V=window.__VIL;if(!V||!V.towns||!V.towns.length){tour=setTimeout(go,300);return}const c=V.towns[0];const tx=c[1]-6,tz=c[2]-5;H3.tp(tx,tz,1.35);H3.face(-.6);const spin=()=>{if(!u.o.isConnected){const Q=H3.P;if(back&&Q&&Math.hypot(Q.x-tx,Q.z-tz)<2)H3.tp(back[0],back[1],back[2]);H3.cam(0,.32,6);return}yaw+=.0012;H3.cam(yaw,.42,24);requestAnimationFrame(spin)};spin()};go()}catch(e){}
 u.c.innerHTML=`<div class="jd-poster"><div class="jd-dancheong"></div><div class="jd-ptitle">무이 나라 조달청</div><div class="jd-psub">깨진 국보를 되살리는 조달청 새내기 무이의 이야기</div><div class="jd-dancheong"></div></div><div style="display:flex;justify-content:center;gap:4px;margin:6px 0">${['crown','maebyeong','angbu','najeonham','moonjar'].map(k=>`<div style="width:min(92px,17vw);height:min(92px,17vw);display:grid;place-items:center;background:radial-gradient(circle at 50% 30%,#8a6e52,#2a1e14 78%);border-radius:10px"><img src="${THUMB(k)}" alt="" style="max-width:86%;max-height:86%;object-fit:contain;filter:grayscale(.85) brightness(.6)"></div>`).join('')}</div>
 <p style="margin:6px 0;text-align:left">무이 나라는 옛 보물을 되살리는 일을 가장 귀하게 여기는 나라예요. 그런데 다섯 고을의 국보가 깨지고 말았어요.</p><p style="margin:6px 0;text-align:left">당신은 나라 살림을 맡은 <b>조달청</b>의 새내기 무이예요. 고을마다 <b>방(榜)</b>을 붙여 장인을 구하고, 알맞은 사람에게 맡겨 국보를 되살려 주세요. 곳간의 냥은 ${START}냥뿐이니 아껴 써야 해요.</p><div style="margin:6px 0 4px;text-align:left;font-size:13.5px"><b style="color:#8e2b20">한 고을 = 실제 조달청 순서 그대로</b><div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:4px">${[['방 붙이기','요청·규격·공고'],['장인 고르기','개찰·적격 심사'],['수결과 발굴','계약·이행 감독'],['조각 맞추기','검수'],['의궤 적기','대금·정보 공개']].map((x,i)=>`${i?'<span style="color:#b8a888;align-self:center">›</span>':''}<span style="padding:3px 7px;border-radius:8px;background:#fff8e4;border:1.5px solid #c8a050;font:12.5px 'Do Hyeon',sans-serif;line-height:1.25">${x[0]}<br><small style="color:#8e2b20">${x[1]}</small></span>`).join('')}</div></div>
 <div class="jd-tip">하는 법: 빛기둥이 선 고을로 가서 「방 붙이기」를 눌러요. 왼쪽 위 상자의 단추로 다음 고을에 바로 갈 수 있어요. 키 안내는 왼쪽 위 「조작」 단추에 있어요. 다 마치면 맺음에서 <b>수업 활동지</b>를 A4 한 장으로 뽑을 수 있어요.</div>${KEYS_HTML}<div style="margin-top:12px;display:flex;gap:8px;justify-content:center;flex-wrap:wrap"><button type="button" class="jd-btn" data-ok>첫 방 붙이러 가기</button><button type="button" class="jd-btn g" data-quick>빠른 체험 (경주 한 고을 + 맺음, 약 5분)</button></div>`;
 u.c.querySelector('[data-ok]').onclick=()=>{u.close();ST.intro=1;save();const nx=JOBS.find(j=>!ST.done[j.k]&&j.sp);if(nx)try{window.__H3.tp(nx.sp.x,nx.sp.z+1.2,(nx.sp.y||0)+.5);window.__H3.face(Math.PI)}catch(e){}};u.c.querySelector('[data-quick]').onclick=()=>{u.close();ST.intro=1;ST.quick=1;save();hudDraw();const j=JOBS.find(j=>j.k==='crown');try{window.__H3.tp(j.sp.x,j.sp.z+1.2,(j.sp.y||0)+.5);window.__H3.face(Math.PI)}catch(e){}setTimeout(()=>{try{window.__H3.say('빠른 체험이에요. 경주 방 앞에서 「방 붙이기」를 눌러 시작해요.',5)}catch(e){}},600)}}

/* ---------- 길 안내: 무이 머리 위 금빛 화살표가 다음 목적지를 가리킴(가까우면 숨김) ---------- */
const GUIDE={d:0};(function guide(){const H=window.__H3;if(!H||!H.P||!X.scene){setTimeout(guide,500);return}
 const g=new THREE.Group();const am=new THREE.MeshBasicMaterial({color:0xffc84a,transparent:true,opacity:.95,depthTest:false,side:THREE.DoubleSide,toneMapped:false});const sh=new THREE.Shape();sh.moveTo(0,.9);sh.lineTo(.55,.25);sh.lineTo(.2,.25);sh.lineTo(.2,-.6);sh.lineTo(-.2,-.6);sh.lineTo(-.2,.25);sh.lineTo(-.55,.25);sh.lineTo(0,.9);const ar=new THREE.Mesh(new THREE.ShapeGeometry(sh),am);ar.rotation.x=-Math.PI/2+.55;ar.renderOrder=8;const ol=new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(sh.getPoints().map(p=>new THREE.Vector3(p.x,p.y,.01))),new THREE.LineBasicMaterial({color:0x5a3a10,depthTest:false}));ol.rotation.copy(ar.rotation);ol.renderOrder=9;g.add(ar,ol);g.visible=false;X.scene.add(g);
 /* 11/17 밤: 진행 중인 사건(수레 추격·밤 경비·긴급 조달·날씨·호송·파발·연등·주민 부탁 진행)이 있으면 다른 알림 창이 끼어들지 않게 */window.__EVACTIVE=()=>{try{return !!((NGT&&NGT.active())||(CHS&&CHS.active())||(EMG&&EMG.active())||(WX&&WX.active())||(RLY&&RLY.active())||(ESC&&ESC.active())||(LAN&&LAN.active()))}catch(e){return false}};
 let lastHud=0;const tick=()=>{try{const P=H.P;let T=null;if(NGT&&NGT.active())T=NGT.target();else if(CHS&&CHS.active())T=CHS.target();else if(MKT&&MKT.carrying())T=MKT.target();else if(VIL&&VIL.active())T=VIL.target();else if(EMG&&EMG.active())T=EMG.target();else if(WX&&WX.active())T=WX.target();else if(RLY&&RLY.active())T=RLY.target();else if(ESC&&ESC.active())T=ESC.target();else if(LAN&&LAN.active())T=LAN.target();else if(window.__OTOUR&&window.__OTOUR.active())T=window.__OTOUR.target();else{const cj=ST.cur&&!ST.done[ST.cur.k]?JOBS.find(j=>j.k===ST.cur.k&&j.sp):null;const nx=cj||JOBS.find(j=>!ST.done[j.k]&&j.sp);if(nx)T=nx.sp}
  const busy=document.querySelector('.jd-ov,body>div[data-mg]');if(T&&P&&!busy){const dx=T.x-P.x,dz=T.z-P.z,d=Math.hypot(dx,dz);GUIDE.d=d;g.visible=d>((CHS&&CHS.active())||(NGT&&NGT.active())||(VIL&&VIL.active())?3:14);const a=Math.atan2(dx,dz);g.position.set(P.x+Math.sin(a)*1.6,P.y+2.3+Math.sin(performance.now()/300)*.1,P.z+Math.cos(a)*1.6);g.rotation.y=a+Math.PI}else g.visible=false;
  if(performance.now()-lastHud>800&&!busy&&Math.abs(GUIDE.d-(GUIDE.shown||0))>4&&!(EMG&&EMG.active())&&!(WX&&WX.active())&&!(RLY&&RLY.active())&&!(ESC&&ESC.active())&&!(LAN&&LAN.active())&&!(CHS&&CHS.active())&&!(NGT&&NGT.active())){lastHud=performance.now();GUIDE.shown=GUIDE.d;hudDraw()}}catch(e){}requestAnimationFrame(tick)};tick()})();

